-- Карта за ДТВ на педагогическите специалисти 2026/2027 (Приложение № 4 към чл. 24, ал. 1 от Наредба № 4/20.04.2017 г.,
-- във варианта на ЦСОП – Варна). Една обща карта за всички педагози. Корекции — от „Оценяване → Карти“.
insert into public.eval_templates (code, kind, grp, name, title, adopted, col_label, roles, criteria, base, total, sort) values
('dtv_ped', 'dtv', 'ped', 'ДТВ — педагогически специалист (Прил. № 4)',
 'КАРТА ЗА ОЦЕНЯВАНЕ НА ПОСТИГНАТИТЕ РЕЗУЛТАТИ ОТ ТРУДА НА ПЕДАГОГИЧЕСКИ СПЕЦИАЛИСТ В ЦЕНТЪР ЗА СПЕЦИАЛНА ОБРАЗОВАТЕЛНА ПОДКРЕПА',
 'Основание: Приложение № 4 към чл. 24, ал. 1 от Наредба № 4 от 20.04.2017 г. за нормиране и заплащане на труда', 'Показател / критерий',
 '{class_teacher,teacher,educator,speech_therapist,psychologist,coordinator,zdud}',
 '[{"n": "1", "g": "Планиране, организация и провеждане на образователно-възпитателния процес", "max": 14, "items": [{"k": "1.1", "t": "Коректно и в срок водене на задължителната документация, свързана с пряката педагогическа дейност.", "max": 3}, {"k": "1.2", "t": "Планиране на обучението или подкрепата съобразно индивидуалните потребности, възможности и актуалното ниво на функциониране на учениците.", "max": 2}, {"k": "1.3", "t": "Адаптиране и преструктуриране на учебното съдържание, задачите и инструкциите според възможностите на учениците.", "max": 1}, {"k": "1.4", "t": "Предварителна подготовка и подбор или разработване на подходящи дидактически материали и средства.", "max": 2}, {"k": "1.5", "t": "Организация на диагностично-терапевтичната дейност с децата със СОП в съответствие със заложените в Плана за допълнителна подкрепа за личностно развитие и/или Оценка на функционирането на детето/ученика цели.", "max": 2}, {"k": "1.6", "t": "Адекватно формулиране и поставяне на цели и задачи, съобразно специфичните особености на трудовите задължения.", "max": 2}, {"k": "1.7", "t": "Организация на педагогическата ситуация/учебния час или терапевтичната сесия, осигуряваща активно участие, достъпност и позитивна работна среда.", "max": 2}]}, {"n": "2", "g": "Използване на интерактивни методи, иновации и ИКТ в образователно-възпитателния процес", "max": 10, "items": [{"k": "2.1", "t": "Прилагане на интерактивни, практически и мултисензорни методи, съобразени с индивидуалните възможности на учениците.", "max": 2}, {"k": "2.2", "t": "Целенасочено използване на ИКТ, дигитални ресурси и технически средства в педагогическата работа.", "max": 2}, {"k": "2.3", "t": "Използване на визуални опори, структуриращи средства и при необходимост средства за допълваща и алтернативна комуникация.", "max": 4}, {"k": "2.4", "t": "Разработване/адаптиране и ефективно прилагане на авторски или иновативни педагогически ресурси и практики.", "max": 2}]}, {"n": "3", "g": "Работа в екип за създаване на подходяща образователно-възпитателна среда", "max": 10, "items": [{"k": "3.1", "t": "Активно участие в екипната работа по конкретни ученици – обмен на информация, съгласуване на цели и подходи.", "max": 2}, {"k": "3.2", "t": "Изпълнение и проследяване на договорените екипни решения в собствената педагогическа работа.", "max": 2}, {"k": "3.3", "t": "Ефективно взаимодействие с учители, психолог, логопед, рехабилитатор и други специалисти при решаване на конкретни случаи.", "max": 2}, {"k": "3.4", "t": "Участие в комисии, работни групи и други институционални екипи извън задължителното участие по длъжност.", "max": 2}, {"k": "3.5", "t": "Принос за създаване и поддържане на безопасна, подкрепяща и структурирана среда за учениците. Работа за подобряване на материалната база в училище, грижа за интериора и общите части.", "max": 2}]}, {"n": "4", "g": "Работа с деца и ученици, в т.ч. застрашени от отпадане; в риск; в мултикултурна среда; със СОП и/или хронични заболявания и др.", "max": 7, "items": [{"k": "4.1", "t": "Участие в интердисциплинарна екипна работа със специалисти от социалните услуги и/или други специалисти, включително медицински.", "max": 2}, {"k": "4.2", "t": "Ефективно прилагане на стратегии при поведенчески затруднения, кризисни или други специфични ситуации.", "max": 2}, {"k": "4.3", "t": "Предприемане на допълнителни дейности за осигуряване на редовното посещение и включване в образователния процес на ученици при затруднено взаимодействие със семейството.", "max": 3}]}, {"n": "5", "g": "Работа с деца и ученици за участие в дейности извън центъра – състезания, конкурси, изложби и др.", "max": 5, "items": [{"k": "5.1", "t": "Участие в адаптирани състезания, конкурси и инициативи на общинско и областно ниво (вкл. за приобщаващо образование).", "max": 2}, {"k": "5.2", "t": "Отличие/класиране на регионално, национално или международно ниво (вкл. Спешъл Олимпикс България и сходни специализирани прояви).", "max": 3}]}, {"n": "6", "g": "Работа с родителите", "max": 7, "items": [{"k": "6.1", "t": "Работа с родители/настойници, лични и/или социални асистенти за усвояване и прилагане на техники за развиване на комуникативни способности и умения.", "max": 2}, {"k": "6.2", "t": "Съдействие за включване на родителите в различни форми на обучение, семинари, поддържащи групи, конференции.", "max": 3}, {"k": "6.3", "t": "Участие в родителски срещи, други общоучилищни форми и дейности в детската градина/училището, за разясняване на стратегиите на приобщаващото образование.", "max": 2}]}, {"n": "7", "g": "Работа с деца и ученици в занимания по интереси", "max": 7, "items": [{"k": "7.1", "t": "Организиране и/или активно участие в празници, тематични дни, изложби, концерти, спортни и творчески инициативи на ЦСОП.", "max": 3}, {"k": "7.2", "t": "Организация и участие в училищни и общински празници и мероприятия.", "max": 2}, {"k": "7.3", "t": "Организиране и провеждане на екскурзии, зелени училища, излети.", "max": 2}]}, {"n": "8", "g": "Организиране и провеждане на вътрешна квалификация", "max": 7, "items": [{"k": "8.1", "t": "Организиране и провеждане на вътрешна квалификация в методическото обединение.", "max": 3}, {"k": "8.2", "t": "Изнасяне на открити уроци и доклади пред педагогическите специалисти.", "max": 2}, {"k": "8.3", "t": "Създаване и споделяне на методически или дидактически ресурс за използване от педагогическия екип.", "max": 2}]}, {"n": "9", "g": "Разработване и реализиране на проекти", "max": 5, "items": [{"k": "9.1", "t": "Участие в проучване и подготовка на проектно предложение/програма, приложима към дейността на ЦСОП.", "max": 2}, {"k": "9.2", "t": "Участие в разработване и реализиране на вътрешни проекти за ЦСОП, мини проекти.", "max": 2}, {"k": "9.3", "t": "Реализиране и/или отчитане на конкретни дейности по одобрен проект или национална/друга програма.", "max": 1}]}, {"n": "10", "g": "Получени професионални отличия и награди през оценявания период и други избрани от институцията показатели", "max": 28, "items": [{"k": "10.1", "t": "Получено професионално отличие или награда през оценявания период.", "max": 3}, {"k": "10.2", "t": "Участие като лектор/обучител или представяне на собствен професионален опит във външен форум, конференция, семинар или вътрешноинституционално обучение.", "max": 4}, {"k": "10.3", "t": "Публикуване или официално споделяне на авторски професионален/методически материал извън ЦСОП.", "max": 2}, {"k": "10.4", "t": "Инициативност – предложено и реализирано решение за подобряване на организацията или качеството на педагогическата дейност.", "max": 2}, {"k": "10.5", "t": "Иницииране и организиране на институционална инициатива с участие на ученици, родители, партньори или общественост.", "max": 3}, {"k": "10.6.1", "t": "Трудова дисциплина: стриктно изпълнение на функционалните задължения в длъжностната характеристика.", "max": 2}, {"k": "10.6.2", "t": "Трудова дисциплина: изпълнение на дежурство.", "max": 1}, {"k": "10.6.3", "t": "Трудова дисциплина: проява на творчество или инициативност при изпълнение на възложената работа.", "max": 3}, {"k": "10.7", "t": "Участие в разработване и реализиране на дейности за подготовка на учениците за социално включване и професионална реализация.", "max": 2}, {"k": "10.8", "t": "Иницииране и реализиране на дейности за подкрепа на социалното включване на децата и учениците извън средата на ЦСОП.", "max": 2}, {"k": "10.9", "t": "Участие в дейности по професионално ориентиране и подготовка за последваща професионална реализация на учениците.", "max": 2}, {"k": "10.10", "t": "Участие в разработване и прилагане на програми за включване на родителите в специалната образователна подкрепа.", "max": 2}]}]', '[{"n": "1", "g": "Планиране, организация и провеждане на образователно-възпитателния процес", "max": 14, "items": [{"k": "1.1", "t": "Коректно и в срок водене на задължителната документация, свързана с пряката педагогическа дейност.", "max": 3}, {"k": "1.2", "t": "Планиране на обучението или подкрепата съобразно индивидуалните потребности, възможности и актуалното ниво на функциониране на учениците.", "max": 2}, {"k": "1.3", "t": "Адаптиране и преструктуриране на учебното съдържание, задачите и инструкциите според възможностите на учениците.", "max": 1}, {"k": "1.4", "t": "Предварителна подготовка и подбор или разработване на подходящи дидактически материали и средства.", "max": 2}, {"k": "1.5", "t": "Организация на диагностично-терапевтичната дейност с децата със СОП в съответствие със заложените в Плана за допълнителна подкрепа за личностно развитие и/или Оценка на функционирането на детето/ученика цели.", "max": 2}, {"k": "1.6", "t": "Адекватно формулиране и поставяне на цели и задачи, съобразно специфичните особености на трудовите задължения.", "max": 2}, {"k": "1.7", "t": "Организация на педагогическата ситуация/учебния час или терапевтичната сесия, осигуряваща активно участие, достъпност и позитивна работна среда.", "max": 2}]}, {"n": "2", "g": "Използване на интерактивни методи, иновации и ИКТ в образователно-възпитателния процес", "max": 10, "items": [{"k": "2.1", "t": "Прилагане на интерактивни, практически и мултисензорни методи, съобразени с индивидуалните възможности на учениците.", "max": 2}, {"k": "2.2", "t": "Целенасочено използване на ИКТ, дигитални ресурси и технически средства в педагогическата работа.", "max": 2}, {"k": "2.3", "t": "Използване на визуални опори, структуриращи средства и при необходимост средства за допълваща и алтернативна комуникация.", "max": 4}, {"k": "2.4", "t": "Разработване/адаптиране и ефективно прилагане на авторски или иновативни педагогически ресурси и практики.", "max": 2}]}, {"n": "3", "g": "Работа в екип за създаване на подходяща образователно-възпитателна среда", "max": 10, "items": [{"k": "3.1", "t": "Активно участие в екипната работа по конкретни ученици – обмен на информация, съгласуване на цели и подходи.", "max": 2}, {"k": "3.2", "t": "Изпълнение и проследяване на договорените екипни решения в собствената педагогическа раб